from batch07 import *
start('ipv6','IPv6 — ND, SLAAC i diagnostyka','1.8',['https://www.cisco.com/c/en/us/td/docs/ios/ipv6/configuration/guide/xe-17/ipv6-xe-17-book-cat8000/m_ip6-addrg-bsc-con.html'],True)
q('ND zamiast ARP','Jak IPv6 realizuje rozwiązywanie adresu sąsiada na Ethernet?','Przez Neighbor Discovery z ICMPv6',['Przez ARP z adresem 128-bitowym|IPv6 nie używa ARP.','Przez obowiązkowy DNS PTR|PTR nie rozwiązuje adresu warstwy drugiej.','Przez tablicę NAT IPv4|NAT IPv4 nie jest mechanizmem IPv6 ND.'],'Neighbor Solicitation i Advertisement są częścią ND i służą m.in. ustalaniu adresu warstwy drugiej.')
q('Duplicate Address Detection','Co sprawdza DAD przed normalnym użyciem adresu IPv6?','Czy ten adres jest już używany na łączu',['Czy działa DNS dla całego Internetu|DAD nie jest testem DNS.','Czy wybrano najlepszą trasę BGP|DAD nie oblicza tras.','Czy adres jest z publicznej puli IPv4|Dotyczy IPv6 na lokalnym łączu.'],'Wykrycie konfliktu uniemożliwia zwykłe użycie adresu; trzeba usunąć przyczynę duplikacji.')
c('Link-local next-hop','W labie dodaj trasę do 2001:db8:200::/64 przez fe80::2 na G0/1. Prefix celu jest wpisany; uzupełnij interfejs i next-hop.','R1(config)# ipv6 route 2001:db8:200::/64 {{b0}} {{b1}}',['GigabitEthernet0/1',(['fe80::2'],'ipv6')],'Link-local ma zasięg łącza, dlatego trasa wymaga wskazania interfejsu wyjściowego.')
q('SLAAC a DHCPv6','Skąd typowy host IPv6 dowiaduje się o routerze domyślnym?','Z Router Advertisement',['Wyłącznie z DHCPv6, tak jak bramę DHCPv4|Standardowy DHCPv6 nie przekazuje bramy domyślnej jak DHCPv4.','Z MAC źródłowego dowolnej ramki|Dowolna ramka nie jest informacją o routerze.','Z wpisu DNS A|A opisuje IPv4, nie domyślną bramę IPv6.'],'RA i przydział adresu to odrębne elementy konfiguracji hosta.')
c('Domyślna trasa link-local','Skieruj domyślną trasę IPv6 przez fe80::1 na G0/0. Wpisz prefiks domyślny i adres next-hop.','R1(config)# ipv6 route {{b0}} GigabitEthernet0/0 {{b1}}',[(['::/0'],'ipv6_prefix'),(['fe80::1'],'ipv6')],'Jawny interfejs identyfikuje łącze, na którym istnieje link-local bramy.')
q('Adres ULA','Do jakiego zakresu należy adres fd12:3456:789a::1?','Unique Local Address',['Link-local fe80::/10|Podany adres nie zaczyna się od zakresu link-local.','Multicast ff00::/8|Nie ma prefiksu ff.','Loopback ::1|Podany adres nie jest ::1.'],'ULA pochodzi z fc00::/7; typowo lokalnie generowane prefiksy używają fd00::/8.')
q('Adres nieokreślony','Co oznacza :: w IPv6, gdy występuje jako cały adres?','Adres nieokreślony',['Adres loopback|Loopback to ::1.','Adres wszystkich routerów|To adres multicast, np. ff02::2 w zasięgu łącza.','Dowolny adres globalny|:: ma określone specjalne znaczenie.'],'Adres nieokreślony jest używany w określonych procedurach, np. zanim host ma właściwy adres źródłowy.')
q('Loopback IPv6','Jaki adres IPv6 odpowiada loopbackowi hosta?','::1',['::|To adres nieokreślony.','fe80::1|To adres link-local, nie standardowy loopback.','ff02::1|To multicast do wszystkich węzłów na łączu.'],'::1 służy komunikacji z samym sobą i nie jest zwykłym celem routowanym przez sieć.')
c('Napraw zły next-hop','Usuń trasę do 2001:db8:90::/64 przez fe80::9 na G0/1 i dodaj ją przez fe80::2 na tym samym interfejsie.','R1(config)# no ipv6 route 2001:db8:90::/64 GigabitEthernet0/1 {{b0}}\nR1(config)# ipv6 route {{b1}} GigabitEthernet0/1 {{b2}}',[(['fe80::9'],'ipv6'),(['2001:db8:90::/64'],'ipv6_prefix'),(['fe80::2'],'ipv6')],'Trasa z link-local wymaga zarówno poprawnego sąsiada, jak i właściwego łącza.')
q('Wiele adresów na interfejsie','Czy jeden interfejs IPv6 może mieć jednocześnie link-local i adres globalny?','Tak',['Nie, zawsze dokładnie jeden adres|IPv6 pozwala na wiele adresów o różnych rolach.','Tylko przy wyłączonym ND|ND nie musi być wyłączone.','Tylko na loopback|Nie jest to ograniczone do loopbacka.'],'Wiele adresów na interfejsie jest normalne; aplikacja wybiera odpowiedni adres źródłowy według zasad stosu.')
c('Dwa adresy i stan','Na G0/2 przypisz 2001:db8:72::1/64 oraz link-local fe80::72; podnieś port.','R1(config-if)# ipv6 address {{b0}}\nR1(config-if)# ipv6 address {{b1}} link-local\nR1(config-if)# {{b2}}',[(['2001:db8:72::1/64'],'ipv6_prefix'),(['fe80::72'],'ipv6'),'no shutdown'],'Adres globalny i link-local mają różny zasięg; oba muszą być poprawne dla danego łącza.')
q('Adres multicast','Który z podanych adresów jest multicastem IPv6?','ff02::1',['2001:db8::1|To adres unicast z prefiksu dokumentacyjnego.','fe80::1|To link-local unicast.','::1|To adres loopback, a nie multicast.'],'Multicast IPv6 używa ff00::/8; ff02::1 ma zasięg pojedynczego łącza.')
q('Blokowanie ICMPv6','Dlaczego szerokie odrzucenie całego ICMPv6 może zepsuć nawet lokalną łączność?','ICMPv6 obsługuje ważne funkcje ND i komunikaty kontrolne',['Ponieważ IPv6 jest szyfrowane przez ICMPv6|ICMPv6 nie zapewnia takiego szyfrowania.','Ponieważ każdy HTTP jest pakietem ICMPv6|HTTP korzysta z odpowiedniego transportu, nie jest ND.','Ponieważ ARP używa portu ICMPv6|IPv6 nie używa ARP.'],'Filtrowanie ICMPv6 musi uwzględniać typy niezbędne do poprawnego działania stosu.')
q('RA z prefiksem bez SLAAC','RA ogłasza prefiks, ale nie pozwala użyć go do autonomicznej konfiguracji adresu. Czy sam prefiks gwarantuje adres SLAAC?','Nie',['Tak, każdy prefiks w RA zawsze uruchamia SLAAC|Znaczenie mają flagi oraz parametry prefiksu.','Tak, bo wszystkie adresy tworzy DHCPv4|DHCPv4 nie konfiguruje IPv6.','Tak, jeżeli router ma wysokie AD|AD nie steruje flagami RA.'],'Należy odróżniać informację o prefiksie on-link od zgody na autonomiczną konfigurację.')
c('Trzy widoki IPv6','Pokaż skrócone interfejsy IPv6, tabelę sąsiadów oraz trasy statyczne IPv6.','R1# show ipv6 interface {{b0}}\nR1# show ipv6 {{b1}}\nR1# show ipv6 route {{b2}}',['brief','neighbors','static'],'Stan interfejsu, ND i routing sprawdzają różne warunki poprawnego przekazywania IPv6.')
q('Podział /56','Ile podsieci /64 mieści się w jednym /56?','256',['8|Różnica ośmiu bitów daje 2^8 kombinacji.','64|To nie wynik różnicy długości prefiksów.','65536|To wynik podziału /48 na /64.'],'64 − 56 = 8 bitów, więc można wyznaczyć 256 podsieci /64.')
c('Rozdziel nowe LAN-y','G0/0 ma otrzymać 2001:db8:ab00:1::1/64, G0/1 adres 2001:db8:ab00:2::1/64. Włącz też globalne przekazywanie IPv6.','R1(config)# ipv6 {{b0}}\nR1(config)# interface GigabitEthernet0/0\nR1(config-if)# ipv6 address {{b1}}\nR1(config-if)# exit\nR1(config)# interface GigabitEthernet0/1\nR1(config-if)# ipv6 address {{b2}}',['unicast-routing',(['2001:db8:ab00:1::1/64'],'ipv6_prefix'),(['2001:db8:ab00:2::1/64'],'ipv6_prefix')],'Różne LAN-y otrzymują różne prefiksy; samo nadanie adresów nie zastępuje globalnego routingu IPv6.')
q('IPv4 działa, IPv6 nie','Dual-stack host działa po IPv4, ale po IPv6 nie dociera poza LAN. Co trzeba sprawdzić osobno?','Adresację, RA/trasę domyślną, ND i routing IPv6',['Uznać IPv6 za sprawne dzięki działaniu IPv4|Stosy mają osobną konfigurację i tablice.','Wyłącznie DNS A|IPv6 wymaga również odpowiedniej drogi i parametrów.','Zmienić NAT IPv4 niezależnie od objawu|To nie bezpośrednia diagnostyka drogi IPv6.'],'Działanie jednej rodziny adresowej nie dowodzi działania drugiej.')
end()
